// Codec library (src/codec) unit tests: the decoders against vectors from
// independent encoders -- one-shot, and streamed through output buffers of
// every awkward size from memory and from a pull callback -- their
// behaviour on truncated, corrupted and over-long input, the small classic
// codecs against hand-built streams, chaining, the encoders' round trips,
// the checksums against their published check values, and the dispatch
// table.  StuffIt's methods 3, 13 and 15: stuffit.c.
//
// vectors.h is generated by make_vectors.py (zlib, libbz2 and liblzma
// through Python, Apple's LZFSE encoder through pyliblzfse); the data each
// vector decodes to is regenerated by vec_gen() (vec_gen.h), the same
// generator.
// ADC is also covered by the ndif suite, dcmp by the resfork suite and the
// checkpoint run lengths by the checkpoint suite.

#include "codec.h"
#include "test_assert.h"
#include "vec_gen.h"
#include "vectors.h"

void stuffit_tests(void); // stuffit.c

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N_VECTORS (sizeof(k_vectors) / sizeof(k_vectors[0]))

// The largest encoding the exhaustive truncation and corruption tests walk.
#define EXHAUSTIVE_MAX 4096

// ---- data ----------------------------------------------------------------

// A copy of `n` bytes, so a test may change them.
static uint8_t *dup_bytes(const uint8_t *p, size_t n) {
    uint8_t *b = malloc(n ? n : 1);
    ASSERT_TRUE(b != NULL);
    memcpy(b, p, n);
    return b;
}

// Report the vector a failing assertion is about.
static void note(const vector_t *v, const char *what) {
    fprintf(stderr, "       %s: %s\n", v->name, what);
}

// ---- decoding the vectors --------------------------------------------------

// Every vector decodes to its data: with the exact capacity, with room to
// spare, and -- one byte short -- not at all.
TEST(vectors_decode_exactly) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len + 64);
        ASSERT_TRUE(out != NULL);

        int64_t n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len);
        if (n != (int64_t)v->len)
            note(v, codec_strerror(n));
        ASSERT_EQ_INT((int)v->len, (int)n);
        ASSERT_TRUE(memcmp(out, want, v->len) == 0);

        memset(out, 0xA5, v->len + 64);
        n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len + 64);
        ASSERT_EQ_INT((int)v->len, (int)n);
        ASSERT_TRUE(memcmp(out, want, v->len) == 0);
        for (size_t k = v->len; k < v->len + 64; k++)
            ASSERT_TRUE(out[k] == 0xA5); // nothing written past the data

        if (v->len) {
            n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len - 1);
            if (n != CODEC_ERR_OVERFLOW)
                note(v, "one byte short");
            ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)n);
        }
        free(out);
        free(want);
    }
}

// Every proper prefix of an encoding either fails or -- where the format
// lets a stream end early, as zlib's optional trailer does -- decodes to
// exactly the data.  Never a wrong success, never a read past the prefix
// (each prefix is its own allocation, so ASan sees any overrun).
TEST(truncation_fails_cleanly) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if (v->enc_len > EXHAUSTIVE_MAX)
            continue;
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len + 1);
        ASSERT_TRUE(out != NULL);
        for (size_t cut = 0; cut < v->enc_len; cut++) {
            uint8_t *part = dup_bytes(v->enc, cut);
            int64_t n = codec_decode((codec_id_t)v->codec, part, cut, out, v->len);
            if (n >= 0) {
                if (n != (int64_t)v->len || memcmp(out, want, v->len) != 0)
                    note(v, "a truncated stream decoded to the wrong data");
                ASSERT_EQ_INT((int)v->len, (int)n);
                ASSERT_TRUE(memcmp(out, want, v->len) == 0);
            }
            free(part);
        }
        free(out);
        free(want);
    }
}

// One flipped bit at every byte of an encoding never crashes the decoder or
// writes past the buffer; the result is an error or some output of at most
// the capacity.  (Not every flip is detectable: LZFSE and raw DEFLATE carry
// no checksum.)
TEST(corruption_is_contained) {
    uint32_t x = 12345;
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if (v->enc_len > EXHAUSTIVE_MAX)
            continue;
        size_t cap = v->len + 16;
        uint8_t *out = malloc(cap);
        ASSERT_TRUE(out != NULL);
        for (size_t at = 0; at < v->enc_len; at++) {
            uint8_t *bad = dup_bytes(v->enc, v->enc_len);
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            bad[at] ^= (uint8_t)(1u << (x & 7));
            int64_t n = codec_decode((codec_id_t)v->codec, bad, v->enc_len, out, cap);
            ASSERT_TRUE(n <= (int64_t)cap);
            ASSERT_TRUE(n >= CODEC_ERR_ARG);
            free(bad);
        }
        free(out);
    }
}

// Streams whose framing checksums catch any single flipped bit: bzip2's
// block and stream CRCs and xz's header, block-check and index CRCs.
TEST(checksummed_formats_detect_corruption) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if ((v->codec != CODEC_BZIP2 && v->codec != CODEC_XZ) || v->enc_len > EXHAUSTIVE_MAX || v->len == 0)
            continue;
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len);
        ASSERT_TRUE(out != NULL);
        for (size_t at = 0; at < v->enc_len; at++) {
            for (int bit = 0; bit < 8; bit += 3) {
                uint8_t *bad = dup_bytes(v->enc, v->enc_len);
                bad[at] ^= (uint8_t)(1u << bit);
                int64_t n = codec_decode((codec_id_t)v->codec, bad, v->enc_len, out, v->len);
                // A flip may land in bits the decoder never reads (the final
                // byte's padding, a stream's reserved bits): then the data
                // must still be right.
                if (n >= 0) {
                    if (n != (int64_t)v->len || memcmp(out, want, v->len) != 0)
                        note(v, "an undetected corruption");
                    ASSERT_EQ_INT((int)v->len, (int)n);
                    ASSERT_TRUE(memcmp(out, want, v->len) == 0);
                }
                free(bad);
            }
        }
        free(out);
        free(want);
    }
}

// ---- format details ------------------------------------------------------

// The vector of a data set in a given encoding.
static const vector_t *find(const char *name) {
    for (size_t i = 0; i < N_VECTORS; i++)
        if (strcmp(k_vectors[i].name, name) == 0)
            return &k_vectors[i];
    fprintf(stderr, "[FAIL] no vector %s\n", name);
    exit(1);
}

// Two streams back to back decode as their concatenation, as `bzip2 -c a b`
// and `xz -c a b` write them; xz allows zero padding between, in fours.
TEST(concatenated_streams) {
    const char *pairs[][2] = {
        {"text3k/bz9", "runs/bz1"       },
        {"small/xz",   "text3k/xz_crc32"}
    };
    for (size_t p = 0; p < 2; p++) {
        const vector_t *a = find(pairs[p][0]), *b = find(pairs[p][1]);
        for (size_t pad = 0; pad <= (p ? 8u : 0u); pad += 4) {
            size_t n = a->enc_len + pad + b->enc_len;
            uint8_t *cat = calloc(1, n);
            ASSERT_TRUE(cat != NULL);
            memcpy(cat, a->enc, a->enc_len);
            memcpy(cat + a->enc_len + pad, b->enc, b->enc_len);
            uint8_t *wa = vec_gen(a->kind, a->len, a->seed), *wb = vec_gen(b->kind, b->len, b->seed);
            uint8_t *out = malloc(a->len + b->len);
            ASSERT_TRUE(out != NULL);
            int64_t got = codec_decode((codec_id_t)a->codec, cat, n, out, a->len + b->len);
            ASSERT_EQ_INT((int)(a->len + b->len), (int)got);
            ASSERT_TRUE(memcmp(out, wa, a->len) == 0 && memcmp(out + a->len, wb, b->len) == 0);
            free(out);
            free(wa);
            free(wb);
            free(cat);
        }
    }
    // Padding that is not a multiple of four is not stream padding.
    const vector_t *a = find("small/xz");
    uint8_t *odd = calloc(1, a->enc_len + 3);
    ASSERT_TRUE(odd != NULL);
    memcpy(odd, a->enc, a->enc_len);
    uint8_t out[256];
    ASSERT_TRUE(codec_decode(CODEC_XZ, odd, a->enc_len + 3, out, sizeof(out)) < 0);
    free(odd);
}

// A bzip2 block in the "randomised" form (bzip2 before 0.9.5) is refused as
// unsupported, not decoded wrongly.  Its flag is the bit after the 48-bit
// block magic and the 32-bit block CRC: byte 14, top bit.
TEST(bzip2_randomised_block_is_unsupported) {
    const vector_t *v = find("text3k/bz9");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    ASSERT_TRUE(b[4] == 0x31 && b[5] == 0x41); // the block magic follows "BZh9"
    ASSERT_TRUE((b[14] & 0x80) == 0);
    b[14] |= 0x80;
    uint8_t *out = malloc(v->len);
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_decode(CODEC_BZIP2, b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// An xz block whose filter is not LZMA2 (here delta, 0x03) is unsupported;
// with the header CRC left stale it is a checksum error first.
TEST(xz_other_filters_are_unsupported) {
    const vector_t *v = find("text3k/xz");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    // Stream header (12 bytes), then the block header: size, flags (no
    // optional sizes in this encoder's output), filter id 0x21.
    ASSERT_TRUE(b[13] == 0x00 && b[14] == 0x21);
    size_t hsize = ((size_t)b[12] + 1) * 4;
    b[14] = 0x03;
    uint8_t *out = malloc(v->len);
    ASSERT_EQ_INT(CODEC_ERR_CHECKSUM, (int)codec_decode(CODEC_XZ, b, v->enc_len, out, v->len));
    uint32_t crc = codec_crc32(0, b + 12, hsize - 4);
    for (int k = 0; k < 4; k++)
        b[12 + hsize - 4 + k] = (uint8_t)(crc >> (8 * k));
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_decode(CODEC_XZ, b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// The encodings cover every LZFSE block kind: stored, LZVN and v2.
TEST(lzfse_block_kinds_are_covered) {
    ASSERT_TRUE(memcmp(find("random/lzfse")->enc, "bvx-", 4) == 0);
    ASSERT_TRUE(memcmp(find("text3k/lzfse")->enc, "bvxn", 4) == 0);
    ASSERT_TRUE(memcmp(find("text/lzfse")->enc, "bvx2", 4) == 0);
    ASSERT_TRUE(memcmp(find("zeros/lzfse")->enc, "bvx2", 4) == 0);
    // The unpacked-header form never appears in a stream: refused.
    static const uint8_t v1[16] = {'b', 'v', 'x', '1'};
    uint8_t out[16];
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_decode(CODEC_LZFSE, v1, sizeof(v1), out, sizeof(out)));
    // An unknown magic is malformed.
    static const uint8_t junk[8] = {'b', 'v', 'x', '?'};
    ASSERT_EQ_INT(CODEC_ERR_DATA, (int)codec_decode(CODEC_LZFSE, junk, sizeof(junk), out, sizeof(out)));
}

// The .lzma header's decoded size bounds the output; a stream claiming more
// than the capacity is an overflow before anything is decoded.
TEST(lzma_alone_size_field) {
    const vector_t *v = find("text3k/lzma");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    uint8_t *out = malloc(v->len);
    // Python writes the size as unknown (all ones), so the end marker ends it.
    ASSERT_TRUE(b[5] == 0xFF && b[12] == 0xFF);
    ASSERT_EQ_INT((int)v->len, (int)codec_decode(CODEC_LZMA_ALONE, b, v->enc_len, out, v->len));
    // Stated exactly: decodes to that size (the end marker is not reached).
    for (int k = 0; k < 8; k++)
        b[5 + k] = (uint8_t)((uint64_t)v->len >> (8 * k));
    ASSERT_EQ_INT((int)v->len, (int)codec_decode(CODEC_LZMA_ALONE, b, v->enc_len, out, v->len));
    // Stated larger than the buffer.
    b[5] = (uint8_t)(b[5] + 1);
    ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)codec_decode(CODEC_LZMA_ALONE, b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// ---- the encoders ----------------------------------------------------------

// Compress `in` with `e` (or, NULL, one-shot at `level`), check it decodes
// back to `in`, and answer the encoded size.
static size_t enc_round_trip(codec_id_t id, codec_enc_t *e, int level, const uint8_t *in, size_t len) {
    size_t cap = codec_enc_bound(id, len);
    uint8_t *enc = malloc(cap), *back = malloc(len ? len : 1);
    ASSERT_TRUE(enc != NULL && back != NULL);
    int64_t z = e ? codec_enc_run(e, in, len, enc, cap) : codec_encode(id, level, in, len, enc, cap);
    ASSERT_TRUE(z >= 0 && (size_t)z <= cap);
    if (id == CODEC_XZ)
        ASSERT_TRUE(memcmp(enc,
                           "\xFD"
                           "7zXZ",
                           6) == 0 &&
                    enc[7] == 0x04); // one stream, its check CRC-64
    if (id == CODEC_GSRLE) {
        // No end of its own: the size comes from the container.
        codec_dec_opts_t o = {.src = enc, .len = (size_t)z, .out_len = len};
        codec_dec_t *d = codec_dec_new(id, &o, NULL);
        size_t n = 0;
        ASSERT_EQ_INT(1, codec_dec_run(d, back, len, &n));
        ASSERT_EQ_INT((int)len, (int)n);
        codec_dec_free(d);
    } else
        ASSERT_EQ_INT((int)len, (int)codec_decode(id, enc, (size_t)z, back, len));
    ASSERT_TRUE(memcmp(back, in, len) == 0);
    // Not a byte of room to spare: refused, not truncated.
    if (z > 0) {
        int64_t rc =
            e ? codec_enc_run(e, in, len, enc, (size_t)z - 1) : codec_encode(id, level, in, len, enc, (size_t)z - 1);
        ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)rc);
    }
    free(back);
    free(enc);
    return (size_t)z;
}

// Every data set round-trips through every encoder: xz and zlib at the low,
// default and high levels, through one reused encoder per level and
// one-shot; compressible data shrinks, and more effort never costs much
// size.
TEST(encoders_round_trip) {
    static const codec_id_t ids[] = {CODEC_XZ, CODEC_ZLIB, CODEC_GSRLE};
    for (size_t c = 0; c < sizeof(ids) / sizeof(ids[0]); c++) {
        codec_enc_t *e1 = codec_enc_new(ids[c], 300000, 1, NULL), *e6 = codec_enc_new(ids[c], 300000, 6, NULL);
        ASSERT_TRUE(e1 != NULL && e6 != NULL);
        for (size_t i = 0; i < N_VECTORS; i++) {
            const vector_t *v = &k_vectors[i];
            if (v->codec != CODEC_XZ || strstr(v->name, "/xz_"))
                continue; // one vector per data set
            uint8_t *data = vec_gen(v->kind, v->len, v->seed);
            size_t z1 = enc_round_trip(ids[c], e1, 1, data, v->len);
            size_t z6 = enc_round_trip(ids[c], e6, 6, data, v->len);
            size_t z9 = enc_round_trip(ids[c], NULL, 9, data, v->len);
            if (ids[c] != CODEC_GSRLE && (v->kind == 0 || v->kind == 1 || v->kind == 3))
                ASSERT_TRUE(v->len < 1000 || z6 < v->len / 2); // text, runs, zeros
            if (ids[c] == CODEC_GSRLE && (v->kind == 1 || v->kind == 3))
                ASSERT_TRUE(v->len < 1000 || z6 < v->len / 2); // runs, zeros
            ASSERT_TRUE(z6 <= z1 + z1 / 50 && z9 <= z6 + z6 / 50);
            free(data);
        }
        codec_enc_free(e1);
        codec_enc_free(e6);
    }
    // A codec with no encoder, and an input over the encoder's size.
    int err = 0;
    ASSERT_TRUE(codec_enc_new(CODEC_BZIP2, 100, -1, &err) == NULL && err == CODEC_ERR_ARG);
}

// Large inputs cross every LZMA2 chunk limit: 64 KiB coded (text), 2 MiB
// decoded (zeros), and a stretch that does not shrink (random), which goes
// out stored with the model reset after it.
TEST(xz_encoder_chunk_limits) {
    size_t len = 5u << 20;
    uint8_t *b = malloc(len);
    ASSERT_TRUE(b != NULL);
    uint8_t *text = vec_gen(0, 1u << 20, 31), *noise = vec_gen(2, 300000, 37);
    memcpy(b, text, 1u << 20); // 1 MiB of text: several coded chunks
    memset(b + (1u << 20), 0, 3u << 20); // 3 MiB of zeros: past 2 MiB decoded
    memcpy(b + (4u << 20), noise, 300000); // incompressible: stored
    memcpy(b + (4u << 20) + 300000, text, len - (4u << 20) - 300000); // text again, matching the first
    size_t z = enc_round_trip(CODEC_XZ, NULL, 6, b, len);
    ASSERT_TRUE(z < len / 3);
    // A stored chunk first, when the data starts incompressible.
    size_t cap = codec_enc_bound(CODEC_XZ, 300000);
    uint8_t *enc = malloc(cap);
    int64_t n = codec_encode(CODEC_XZ, 6, noise, 300000, enc, cap);
    ASSERT_TRUE(n > 300000);
    ASSERT_TRUE(enc[24] == 0x01); // after the stream and block headers
    free(enc);
    free(noise);
    free(text);
    free(b);
}

// ---- streaming ---------------------------------------------------------------

// A codec_pull_fn over a buffer, `chunk` bytes at a time.
typedef struct {
    const uint8_t *p;
    size_t len, pos, chunk;
} pull_src_t;

static int64_t pull_from(void *ctx, uint8_t *buf, size_t cap) {
    pull_src_t *s = ctx;
    size_t n = s->len - s->pos;
    if (n > cap)
        n = cap;
    if (n > s->chunk)
        n = s->chunk;
    memcpy(buf, s->p + s->pos, n);
    s->pos += n;
    return (int64_t)n;
}

// Decode with `d` through output buffers of `step` bytes into `out` (room
// for len + 8): the bytes produced, with *rc the last run's result.
static size_t run_in_steps(codec_dec_t *d, uint8_t *out, size_t len, size_t step, int *rc) {
    size_t got = 0;
    *rc = 0;
    while (*rc == 0) {
        size_t cap = len + 8 - got < step ? len + 8 - got : step, k = 0;
        if (cap == 0)
            break; // more than the data and then some: the caller fails it
        *rc = codec_dec_run(d, out + got, cap, &k);
        ASSERT_TRUE(k <= cap);
        got += k;
    }
    return got;
}

// Every vector decodes the same through the streaming decoder as one-shot:
// output buffers of 1, 7 and 4093 bytes, input from memory and pulled 1 and
// 977 bytes at a time; the decoder ends exactly there and says how much
// input the stream took.
TEST(vectors_stream_at_every_buffer_size) {
    static const size_t steps[] = {1, 7, 4093};
    static const size_t pulls[] = {0, 1, 977}; // 0: memory input
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        uint8_t *want = vec_gen(v->kind, v->len, v->seed), *out = malloc(v->len + 8);
        ASSERT_TRUE(out != NULL);
        for (size_t s = 0; s < 3; s++) {
            for (size_t p = 0; p < 3; p++) {
                if ((steps[s] == 1 || pulls[p] == 1) && v->len > 40000 && !(s == 0 && p == 0))
                    continue; // the slow corners on the small vectors only
                if (steps[s] == 1 && pulls[p] == 1 && v->len > 4000)
                    continue;
                pull_src_t ps = {v->enc, v->enc_len, 0, pulls[p]};
                codec_dec_opts_t o = {.out_len = CODEC_LEN_UNKNOWN};
                if (pulls[p]) {
                    o.pull = pull_from;
                    o.pull_ctx = &ps;
                } else {
                    o.src = v->enc;
                    o.len = v->enc_len;
                }
                int err = 0;
                codec_dec_t *d = codec_dec_new((codec_id_t)v->codec, &o, &err);
                ASSERT_TRUE(d != NULL);
                int rc;
                size_t got = run_in_steps(d, out, v->len, steps[s], &rc);
                if (rc != 1 || got != v->len)
                    note(v, codec_dec_message(d));
                ASSERT_EQ_INT(1, rc);
                ASSERT_EQ_INT((int)v->len, (int)got);
                ASSERT_TRUE(memcmp(out, want, v->len) == 0);
                ASSERT_TRUE(codec_dec_total_out(d) == v->len);
                ASSERT_TRUE(codec_dec_consumed(d) <= v->enc_len);
                // Once ended, it stays ended.
                size_t k = 1;
                ASSERT_EQ_INT(1, codec_dec_run(d, out, 1, &k));
                ASSERT_EQ_INT(0, (int)k);
                codec_dec_free(d);
            }
        }
        free(out);
        free(want);
    }
}

// A raw DEFLATE stream says exactly where it ended, so a container's
// trailer (gzip's CRC and size, the next member) can be found after it --
// from memory and when pulled ahead in large chunks.
TEST(deflate_reports_exact_consumption) {
    const vector_t *v = find("text3k/deflate");
    size_t n = v->enc_len + 13;
    uint8_t *b = malloc(n), *out = malloc(v->len);
    ASSERT_TRUE(b != NULL && out != NULL);
    memcpy(b, v->enc, v->enc_len);
    memset(b + v->enc_len, 0xEE, 13); // a trailer the stream must not claim
    for (int p = 0; p < 2; p++) {
        pull_src_t ps = {b, n, 0, 65536};
        codec_dec_opts_t o = {.src = b, .len = n, .out_len = CODEC_LEN_UNKNOWN};
        if (p) {
            o.src = NULL;
            o.len = 0;
            o.pull = pull_from;
            o.pull_ctx = &ps;
        }
        codec_dec_t *d = codec_dec_new(CODEC_DEFLATE, &o, NULL);
        size_t k = 0;
        ASSERT_EQ_INT(1, codec_dec_run(d, out, v->len, &k));
        ASSERT_EQ_INT((int)v->len, (int)k);
        ASSERT_EQ_INT((int)v->enc_len, (int)codec_dec_consumed(d));
        codec_dec_free(d);
    }
    free(out);
    free(b);
}

// A pull error reaches the caller as itself, after the bytes before it.
static int64_t pull_fails(void *ctx, uint8_t *buf, size_t cap) {
    pull_src_t *s = ctx;
    if (s->pos >= s->len / 2)
        return -42;
    return pull_from(ctx, buf, cap);
}

TEST(pull_errors_are_reported) {
    const vector_t *v = find("text/zlib");
    pull_src_t ps = {v->enc, v->enc_len, 0, 512};
    codec_dec_opts_t o = {.pull = pull_fails, .pull_ctx = &ps, .out_len = CODEC_LEN_UNKNOWN};
    codec_dec_t *d = codec_dec_new(CODEC_ZLIB, &o, NULL);
    uint8_t *out = malloc(v->len + 8);
    int rc;
    size_t got = run_in_steps(d, out, v->len, 4096, &rc);
    ASSERT_EQ_INT(-42, rc);
    ASSERT_TRUE(got < v->len);
    uint8_t *want = vec_gen(v->kind, v->len, v->seed);
    ASSERT_TRUE(memcmp(out, want, got) == 0); // what came out before it is right
    ASSERT_TRUE(*codec_dec_message(d) != 0);
    codec_dec_free(d);
    free(want);
    free(out);
}

// One decoder's output is another's input (codec_dec_pull): a zlib stream
// whose payload is itself a zlib stream.
TEST(decoders_chain) {
    uint8_t *data = vec_gen(0, 50000, 7);
    size_t cap1 = codec_enc_bound(CODEC_ZLIB, 50000);
    uint8_t *inner = malloc(cap1);
    int64_t n1 = codec_encode(CODEC_ZLIB, 6, data, 50000, inner, cap1);
    ASSERT_TRUE(n1 > 0);
    size_t cap2 = codec_enc_bound(CODEC_ZLIB, (size_t)n1);
    uint8_t *outer = malloc(cap2);
    int64_t n2 = codec_encode(CODEC_ZLIB, 1, inner, (size_t)n1, outer, cap2);
    ASSERT_TRUE(n2 > 0);
    codec_dec_opts_t o1 = {.src = outer, .len = (size_t)n2, .out_len = CODEC_LEN_UNKNOWN};
    codec_dec_t *d1 = codec_dec_new(CODEC_ZLIB, &o1, NULL);
    codec_dec_opts_t o2 = {.pull = codec_dec_pull, .pull_ctx = d1, .out_len = CODEC_LEN_UNKNOWN};
    codec_dec_t *d2 = codec_dec_new(CODEC_ZLIB, &o2, NULL);
    uint8_t *back = malloc(50000 + 8);
    int rc;
    ASSERT_EQ_INT(50000, (int)run_in_steps(d2, back, 50000, 333, &rc));
    ASSERT_EQ_INT(1, rc);
    ASSERT_TRUE(memcmp(back, data, 50000) == 0);
    codec_dec_free(d2);
    codec_dec_free(d1);
    free(back);
    free(outer);
    free(inner);
    free(data);
}

// codec_dec_stack: the same chain with the outer decoder owning the inner
// one (LeakSanitizer sees it freed), and the inner one's fault reported in
// its own words.
TEST(stacked_decoder_owns_its_input) {
    uint8_t *data = vec_gen(1, 30000, 11);
    size_t cap1 = codec_enc_bound(CODEC_ZLIB, 30000);
    uint8_t *inner = malloc(cap1);
    int64_t n1 = codec_encode(CODEC_ZLIB, 6, data, 30000, inner, cap1);
    size_t cap2 = codec_enc_bound(CODEC_ZLIB, (size_t)n1);
    uint8_t *outer = malloc(cap2);
    int64_t n2 = codec_encode(CODEC_ZLIB, 6, inner, (size_t)n1, outer, cap2);
    ASSERT_TRUE(n1 > 0 && n2 > 0);
    codec_dec_opts_t o = {.src = outer, .len = (size_t)n2, .out_len = CODEC_LEN_UNKNOWN};
    codec_dec_opts_t top = {.out_len = 30000, .check = CODEC_CHECK_CRC32, .check_value = codec_crc32(0, data, 30000)};
    codec_dec_t *d = codec_dec_stack(codec_dec_new(CODEC_ZLIB, &o, NULL), CODEC_ZLIB, &top, NULL);
    ASSERT_TRUE(d != NULL);
    uint8_t *back = malloc(30000 + 8);
    int rc;
    ASSERT_EQ_INT(30000, (int)run_in_steps(d, back, 30000, 777, &rc));
    ASSERT_EQ_INT(1, rc);
    ASSERT_TRUE(memcmp(back, data, 30000) == 0);
    codec_dec_free(d); // frees the inner one too
    // A corrupt inner stream: the outer one fails with the inner one's message.
    outer[(size_t)n2 / 2] ^= 0x55;
    outer[(size_t)n2 / 2 + 1] ^= 0x33;
    d = codec_dec_stack(codec_dec_new(CODEC_ZLIB, &o, NULL), CODEC_ZLIB, &top, NULL);
    run_in_steps(d, back, 30000, 4096, &rc);
    ASSERT_TRUE(rc < 0);
    ASSERT_TRUE(strncmp(codec_dec_message(d), "zlib:", 5) == 0 || strncmp(codec_dec_message(d), "deflate:", 8) == 0 ||
                strstr(codec_dec_message(d), "checksum") != NULL);
    codec_dec_free(d);
    // Bad arguments still free the inner one (or there is none to free).
    int err = 0;
    ASSERT_TRUE(codec_dec_stack(codec_dec_new(CODEC_ZLIB, &o, NULL), (codec_id_t)99, &top, &err) == NULL);
    ASSERT_EQ_INT(CODEC_ERR_ARG, err);
    ASSERT_TRUE(codec_dec_stack(NULL, CODEC_ZLIB, &top, &err) == NULL);
    free(back);
    free(outer);
    free(inner);
    free(data);
}

// pull_close: called once as the decoder is freed, and never when
// codec_dec_new fails (pull_ctx is then still the caller's).
static int g_closed;
static void count_close(void *ctx) {
    (void)ctx;
    g_closed++;
}

TEST(pull_close_owns_the_input) {
    const vector_t *v = find("text3k/deflate");
    pull_src_t ps = {v->enc, v->enc_len, 0, 100};
    codec_dec_opts_t o = {.pull = pull_from, .pull_ctx = &ps, .pull_close = count_close, .out_len = CODEC_LEN_UNKNOWN};
    g_closed = 0;
    codec_dec_t *d = codec_dec_new(CODEC_DEFLATE, &o, NULL);
    ASSERT_TRUE(d != NULL);
    ASSERT_EQ_INT(0, g_closed);
    codec_dec_free(d);
    ASSERT_EQ_INT(1, g_closed);
    o.out_len = CODEC_LEN_UNKNOWN;
    ASSERT_TRUE(codec_dec_new(CODEC_SIT13, &o, NULL) == NULL); // needs out_len
    ASSERT_EQ_INT(1, g_closed);
}

// A checksum the container states, over the decoded bytes: right, wrong,
// and the decoded bytes all delivered before the verdict.
TEST(stated_checksums_are_verified) {
    const vector_t *v = find("text3k/deflate");
    uint8_t *want = vec_gen(v->kind, v->len, v->seed), *out = malloc(v->len + 8);
    static const codec_check_t kinds[] = {CODEC_CHECK_CRC32, CODEC_CHECK_CRC16_ARC};
    for (int k = 0; k < 2; k++) {
        uint32_t good = kinds[k] == CODEC_CHECK_CRC32 ? codec_crc32(0, want, v->len) : codec_crc16_arc(0, want, v->len);
        for (int bad = 0; bad < 2; bad++) {
            codec_dec_opts_t o = {.src = v->enc,
                                  .len = v->enc_len,
                                  .out_len = CODEC_LEN_UNKNOWN,
                                  .check = kinds[k],
                                  .check_value = good ^ (uint32_t)bad};
            codec_dec_t *d = codec_dec_new(CODEC_DEFLATE, &o, NULL);
            int rc;
            size_t got = run_in_steps(d, out, v->len, 7, &rc);
            ASSERT_EQ_INT((int)v->len, (int)got);
            ASSERT_TRUE(memcmp(out, want, v->len) == 0);
            ASSERT_EQ_INT(bad ? CODEC_ERR_CHECKSUM : 1, rc);
            if (bad)
                ASSERT_TRUE(strstr(codec_dec_message(d), "checksum") != NULL);
            codec_dec_free(d);
        }
    }
    free(out);
    free(want);
}

// `exact`: the container's size wins for a codec with an end of its own --
// output past it is dropped, a stream short of it is truncated.
TEST(exact_size_overrides_the_stream) {
    static const uint8_t s[] = {'a', 0x90, 10, 'b'}; // RLE90: "a" x 10, "b"
    codec_dec_opts_t o = {.src = s, .len = sizeof(s), .out_len = 5, .exact = 1};
    codec_dec_t *d = codec_dec_new(CODEC_RLE90, &o, NULL);
    uint8_t out[32];
    int rc;
    ASSERT_EQ_INT(5, (int)run_in_steps(d, out, 5, 3, &rc));
    ASSERT_EQ_INT(1, rc);
    ASSERT_TRUE(memcmp(out, "aaaaa", 5) == 0);
    codec_dec_free(d);
    o.out_len = 20;
    d = codec_dec_new(CODEC_RLE90, &o, NULL);
    run_in_steps(d, out, 20, 3, &rc);
    ASSERT_EQ_INT(CODEC_ERR_TRUNCATED, rc);
    codec_dec_free(d);
    // Without it, the same stream past a limit is an overflow.
    o.exact = 0;
    o.out_len = 5;
    d = codec_dec_new(CODEC_RLE90, &o, NULL);
    run_in_steps(d, out, 5, 3, &rc);
    ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, rc);
    codec_dec_free(d);
    o.out_len = CODEC_LEN_UNKNOWN;
    o.exact = 1;
    ASSERT_TRUE(codec_dec_new(CODEC_RLE90, &o, NULL) == NULL); // exact needs a size
}

// ---- gzip ------------------------------------------------------------------

// A gzip member around a DEFLATE vector: header (with the optional fields
// `flg` asks for), the stream, its CRC-32 and size.  Appended to *b.
static void gz_member(uint8_t **b, size_t *n, const vector_t *v, int flg, uint32_t crc_xor) {
    uint8_t *want = vec_gen(v->kind, v->len, v->seed);
    uint8_t h[64];
    size_t k = 0;
    h[k++] = 0x1F, h[k++] = 0x8B, h[k++] = 8, h[k++] = (uint8_t)flg;
    for (int i = 0; i < 6; i++)
        h[k++] = (uint8_t)i; // mtime, xfl, os
    if (flg & 0x04) { // FEXTRA: a 4-byte subfield
        h[k++] = 4, h[k++] = 0, h[k++] = 'A', h[k++] = 'B', h[k++] = 0, h[k++] = 0;
    }
    if (flg & 0x08) // FNAME
        memcpy(h + k, "name\0", 5), k += 5;
    if (flg & 0x10) // FCOMMENT
        memcpy(h + k, "note\0", 5), k += 5;
    if (flg & 0x02) { // FHCRC: the low 16 bits of the header's CRC-32
        uint32_t c = codec_crc32(0, h, k);
        h[k++] = (uint8_t)c, h[k++] = (uint8_t)(c >> 8);
    }
    *b = realloc(*b, *n + k + v->enc_len + 8);
    memcpy(*b + *n, h, k);
    memcpy(*b + *n + k, v->enc, v->enc_len);
    uint8_t *t = *b + *n + k + v->enc_len;
    uint32_t crc = codec_crc32(0, want, v->len) ^ crc_xor, sz = (uint32_t)v->len;
    for (int i = 0; i < 4; i++)
        t[i] = (uint8_t)(crc >> (8 * i)), t[4 + i] = (uint8_t)(sz >> (8 * i));
    *n += k + v->enc_len + 8;
    free(want);
}

// Every DEFLATE vector as a gzip member, with each header form; members
// back to back decode as their concatenation, streamed and pulled; what
// follows that is not a member is ignored; a bad trailer, header CRC or
// flag is refused.
TEST(gzip_members) {
    static const int flgs[] = {0, 0x08, 0x04 | 0x10 | 0x02, 0x1E};
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if (v->codec != CODEC_DEFLATE || v->enc_len > 300000)
            continue;
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        for (size_t f = 0; f < 4; f++) {
            uint8_t *b = NULL;
            size_t n = 0;
            gz_member(&b, &n, v, flgs[f], 0);
            gz_member(&b, &n, v, flgs[(f + 1) % 4], 0);
            b = realloc(b, n + 5);
            memcpy(b + n, "junk!", 5); // ignored, as gzip -d ignores it
            uint8_t *out = malloc(2 * v->len + 8);
            pull_src_t ps = {b, n + 5, 0, 977};
            codec_dec_opts_t o = {.pull = pull_from, .pull_ctx = &ps, .out_len = CODEC_LEN_UNKNOWN};
            codec_dec_t *d = codec_dec_new(CODEC_GZIP, &o, NULL);
            int rc;
            size_t got = run_in_steps(d, out, 2 * v->len, v->len > 40000 ? 4093 : 7, &rc);
            if (rc != 1)
                note(v, codec_dec_message(d));
            ASSERT_EQ_INT(1, rc);
            ASSERT_EQ_INT((int)(2 * v->len), (int)got);
            ASSERT_TRUE(memcmp(out, want, v->len) == 0 && memcmp(out + v->len, want, v->len) == 0);
            codec_dec_free(d);
            ASSERT_EQ_INT((int)(2 * v->len), (int)codec_decode(CODEC_GZIP, b, n + 5, out, 2 * v->len));
            free(out);
            free(b);
        }
        free(want);
    }
    const vector_t *v = find("text3k/deflate");
    uint8_t *b = NULL, out[4096];
    size_t n = 0;
    gz_member(&b, &n, v, 0, 1); // a CRC off by one
    ASSERT_EQ_INT(CODEC_ERR_CHECKSUM, (int)codec_decode(CODEC_GZIP, b, n, out, sizeof(out)));
    ASSERT_EQ_INT(CODEC_ERR_TRUNCATED, (int)codec_decode(CODEC_GZIP, b, n - 3, out, sizeof(out)));
    b[3] = 0x20; // a reserved flag
    ASSERT_EQ_INT(CODEC_ERR_DATA, (int)codec_decode(CODEC_GZIP, b, n, out, sizeof(out)));
    free(b);
    b = NULL, n = 0;
    gz_member(&b, &n, v, 0x02, 0);
    b[10] ^= 1; // the header CRC
    ASSERT_EQ_INT(CODEC_ERR_CHECKSUM, (int)codec_decode(CODEC_GZIP, b, n, out, sizeof(out)));
    b[0] = 0x1E; // not gzip at all
    ASSERT_EQ_INT(CODEC_ERR_DATA, (int)codec_decode(CODEC_GZIP, b, n, out, sizeof(out)));
    free(b);
}

// ---- the small classic codecs ------------------------------------------------

// Decode a hand-built stream, sized `want_len` (or CODEC_LEN_UNKNOWN), and
// compare; through buffers of 1 byte and of all of it.
static void expect_decode(codec_id_t id, uint32_t flags, const uint8_t *src, size_t len, uint64_t out_len,
                          const char *want, size_t want_len) {
    for (int one = 0; one < 2; one++) {
        codec_dec_opts_t o = {.src = src, .len = len, .out_len = out_len, .flags = flags};
        int err = 0;
        codec_dec_t *d = codec_dec_new(id, &o, &err);
        ASSERT_TRUE(d != NULL);
        uint8_t out[600];
        int rc;
        size_t got = run_in_steps(d, out, want_len, one ? 1 : sizeof(out), &rc);
        if (rc != 1 || got != want_len || memcmp(out, want, want_len) != 0)
            fprintf(stderr, "       %s: rc %d, %zu bytes (%s)\n", codec_name(id), rc, got, codec_dec_message(d));
        ASSERT_EQ_INT(1, rc);
        ASSERT_EQ_INT((int)want_len, (int)got);
        ASSERT_TRUE(memcmp(out, want, want_len) == 0);
        codec_dec_free(d);
    }
}

// The result of decoding a stream that must fail.
static int decode_fails(codec_id_t id, uint32_t flags, const uint8_t *src, size_t len, uint64_t out_len) {
    codec_dec_opts_t o = {.src = src, .len = len, .out_len = out_len, .flags = flags};
    codec_dec_t *d = codec_dec_new(id, &o, NULL);
    ASSERT_TRUE(d != NULL);
    uint8_t out[600];
    int rc;
    run_in_steps(d, out, sizeof(out) - 8, 64, &rc);
    ASSERT_TRUE(rc < 0);
    ASSERT_TRUE(*codec_dec_message(d) != 0);
    codec_dec_free(d);
    return rc;
}

// 0x90 run lengths: StuffIt's rules, and BinHex's two differences.
TEST(rle90_both_dialects) {
    // 'a' x 4 (one, then 3 more), a literal 0x90, 'b', a count of 1.
    static const uint8_t s[] = {'a', 0x90, 4, 0x90, 0, 'b', 0x90, 1, 'c'};
    // StuffIt: after an escaped 0x90 a run repeats the byte before it; a
    // count of 1 adds nothing.
    expect_decode(CODEC_RLE90, 0, s, sizeof(s), CODEC_LEN_UNKNOWN,
                  "aaaa\x90"
                  "bc",
                  7);
    ASSERT_EQ_INT(CODEC_ERR_DATA, decode_fails(CODEC_RLE90, CODEC_RLE90_BINHEX, s, sizeof(s), CODEC_LEN_UNKNOWN));
    // BinHex: an escaped 0x90 is what a run repeats.
    static const uint8_t h[] = {'x', 0x90, 0, 0x90, 3};
    expect_decode(CODEC_RLE90, CODEC_RLE90_BINHEX, h, sizeof(h), CODEC_LEN_UNKNOWN, "x\x90\x90\x90", 4);
    expect_decode(CODEC_RLE90, 0, h, sizeof(h), CODEC_LEN_UNKNOWN, "x\x90xx", 4);
    // A stream that ends inside an escape is truncated.
    static const uint8_t t[] = {'a', 0x90};
    ASSERT_EQ_INT(CODEC_ERR_TRUNCATED, decode_fails(CODEC_RLE90, 0, t, sizeof(t), CODEC_LEN_UNKNOWN));
    // The longest run fills a ring's worth one escape at a time.
    uint8_t big[2 + 2 * 300];
    big[0] = 'z';
    for (int i = 0; i < 300; i++)
        big[1 + 2 * i] = 0x90, big[2 + 2 * i] = 0xFF;
    uint8_t *out = malloc(1 + 300 * 254 + 8);
    codec_dec_opts_t o = {.src = big, .len = 1 + 600, .out_len = CODEC_LEN_UNKNOWN};
    codec_dec_t *d = codec_dec_new(CODEC_RLE90, &o, NULL);
    int rc;
    ASSERT_EQ_INT(1 + 300 * 254, (int)run_in_steps(d, out, 1 + 300 * 254, 1000, &rc));
    ASSERT_EQ_INT(1, rc);
    for (int i = 0; i < 1 + 300 * 254; i++)
        ASSERT_TRUE(out[i] == 'z');
    codec_dec_free(d);
    free(out);
}

// Compact Pro's run lengths: the N - 2 rule, the half escape, a literal 0x81.
TEST(cpt_rle_escapes) {
    // 'a', then 0x81 0x82 5: 'a' once now and 3 more (5 - 2); 0x81 0x81 'q':
    // a literal 0x81, then the second 0x81 escapes 'q' (0x81 'q'); 0x81 0x82 0:
    // 0x81 then 0x82.
    static const uint8_t s[] = {'a', 0x81, 0x82, 5, 0x81, 0x81, 'q', 0x81, 0x82, 0, 'z'};
    static const char want[] = "aaaaa\x81\x81q\x81\x82z";
    expect_decode(CODEC_CPT_RLE, 0, s, sizeof(s), sizeof(want) - 1, want, sizeof(want) - 1);
    // Sized: it ends at the size, mid-run included ...
    expect_decode(CODEC_CPT_RLE, 0, s, sizeof(s), 3, "aaa", 3);
    // ... and input that runs out short of it is truncated.
    ASSERT_EQ_INT(CODEC_ERR_TRUNCATED, decode_fails(CODEC_CPT_RLE, 0, s, sizeof(s), 100));
    // A sized codec needs its size.
    int err = 0;
    codec_dec_opts_t o = {.src = s, .len = sizeof(s), .out_len = CODEC_LEN_UNKNOWN};
    ASSERT_TRUE(codec_dec_new(CODEC_CPT_RLE, &o, &err) == NULL && err == CODEC_ERR_ARG);
}

// StuffIt's LZW: literals, a string, the KwKwK case, a clear code and the
// padding after it -- codes LSB-first, 9 bits until the dictionary fills
// 512 entries.
typedef struct {
    uint8_t buf[256];
    size_t bit;
} lsb_writer;

static void lsb_put(lsb_writer *w, uint32_t v, int n) {
    for (int i = 0; i < n; i++, w->bit++)
        if ((v >> i) & 1)
            w->buf[w->bit / 8] |= (uint8_t)(1u << (w->bit % 8));
}

TEST(sit_lzw_strings_and_clear) {
    static lsb_writer w;
    memset(&w, 0, sizeof(w));
    lsb_put(&w, 'a', 9); // a
    lsb_put(&w, 'b', 9); // b       (257 = ab)
    lsb_put(&w, 257, 9); // ab      (258 = ba)
    lsb_put(&w, 259, 9); // KwKwK: aba (259 = aba)
    lsb_put(&w, 256, 9); // clear: the 5th code of its group of 8 ...
    lsb_put(&w, 0, 9 * 3); // ... so 3 codes of padding
    lsb_put(&w, 'z', 9);
    expect_decode(CODEC_SIT_LZW, 0, w.buf, (w.bit + 7) / 8, 8, "abababaz", 8);
    // A string code before any string, or past the dictionary, is corrupt.
    memset(&w, 0, sizeof(w));
    lsb_put(&w, 300, 9);
    ASSERT_EQ_INT(CODEC_ERR_DATA, decode_fails(CODEC_SIT_LZW, 0, w.buf, 4, 10));
    memset(&w, 0, sizeof(w));
    lsb_put(&w, 'a', 9);
    lsb_put(&w, 400, 9);
    ASSERT_EQ_INT(CODEC_ERR_DATA, decode_fails(CODEC_SIT_LZW, 0, w.buf, 4, 10));
}

// The checkpoint run lengths: chunks, and the size they must keep to.
TEST(gsrle_chunks) {
    static const uint8_t s[] = {0x01, 4, 0, 0, 0, 'r', 0x00, 3, 0, 0, 0, 'l', 'i', 't', 0x01, 0, 0, 0, 0, 'x'};
    expect_decode(CODEC_GSRLE, 0, s, sizeof(s), 7, "rrrrlit", 7);
    ASSERT_EQ_INT(CODEC_ERR_DATA, decode_fails(CODEC_GSRLE, 0, s, sizeof(s), 6)); // a chunk past the size
    ASSERT_EQ_INT(CODEC_ERR_TRUNCATED, decode_fails(CODEC_GSRLE, 0, s, 9, 7)); // a literal cut short
    static const uint8_t bad[] = {0x02, 1, 0, 0, 0};
    ASSERT_EQ_INT(CODEC_ERR_DATA, decode_fails(CODEC_GSRLE, 0, bad, sizeof(bad), 1));
}

// ---- checksums -----------------------------------------------------------

// The published check values: each algorithm over "123456789" (Adler-32
// over "Wikipedia", its usual example), and chaining over a split.
TEST(checksums_match_check_values) {
    const char *s = "123456789";
    ASSERT_TRUE(codec_crc32(0, s, 9) == 0xCBF43926u); // CRC-32/ISO-HDLC
    ASSERT_TRUE(codec_crc32_msb(0, s, 9) == 0xFC891918u); // CRC-32/BZIP2
    ASSERT_TRUE(codec_crc64(0, s, 9) == 0x995DC9BBDF1939FAull); // CRC-64/XZ
    ASSERT_TRUE(codec_adler32(1, "Wikipedia", 9) == 0x11E60398u);
    ASSERT_TRUE(codec_crc16_xmodem(0, s, 9) == 0x31C3); // CRC-16/XMODEM
    ASSERT_TRUE(codec_crc16_arc(0, s, 9) == 0xBB3D); // CRC-16/ARC
    for (size_t k = 0; k <= 9; k++) {
        ASSERT_TRUE(codec_crc32(codec_crc32(0, s, k), s + k, 9 - k) == 0xCBF43926u);
        ASSERT_TRUE(codec_crc32_msb(codec_crc32_msb(0, s, k), s + k, 9 - k) == 0xFC891918u);
        ASSERT_TRUE(codec_crc64(codec_crc64(0, s, k), s + k, 9 - k) == 0x995DC9BBDF1939FAull);
        ASSERT_TRUE(codec_crc16_xmodem(codec_crc16_xmodem(0, s, k), s + k, 9 - k) == 0x31C3);
        ASSERT_TRUE(codec_crc16_arc(codec_crc16_arc(0, s, k), s + k, 9 - k) == 0xBB3D);
    }
    ASSERT_TRUE(codec_crc32(0, NULL, 0) == 0 && codec_crc64(0, NULL, 0) == 0);
}

// ---- dispatch ------------------------------------------------------------

TEST(dispatch_names_and_errors) {
    ASSERT_TRUE(strcmp(codec_name(CODEC_BZIP2), "bzip2") == 0);
    ASSERT_TRUE(strcmp(codec_name(CODEC_LZFSE), "lzfse") == 0);
    ASSERT_TRUE(strcmp(codec_name(CODEC_XZ), "xz") == 0);
    ASSERT_TRUE(strcmp(codec_name((codec_id_t)99), "?") == 0);
    uint8_t out[8];
    ASSERT_EQ_INT(CODEC_ERR_ARG, (int)codec_decode((codec_id_t)99, out, 1, out, sizeof(out)));
    // Stored: exactly the bytes, and no more than fit.
    ASSERT_EQ_INT(3, (int)codec_decode(CODEC_COPY, (const uint8_t *)"abc", 3, out, sizeof(out)));
    ASSERT_TRUE(memcmp(out, "abc", 3) == 0);
    ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)codec_decode(CODEC_COPY, (const uint8_t *)"abc", 3, out, 2));
    // Every code has its own text.
    for (int rc = CODEC_ERR_ARG; rc <= CODEC_ERR_DATA; rc++)
        for (int other = rc + 1; other <= CODEC_ERR_DATA; other++)
            ASSERT_TRUE(strcmp(codec_strerror(rc), codec_strerror(other)) != 0);
    // NULL input is an argument error for every decoder.
    for (int id = CODEC_DEFLATE; id < CODEC_COUNT; id++)
        ASSERT_EQ_INT(CODEC_ERR_ARG, (int)codec_decode((codec_id_t)id, NULL, 4, out, sizeof(out)));
}

