    RUN(vectors_decode_exactly);
    RUN(truncation_fails_cleanly);
    RUN(corruption_is_contained);
    RUN(checksummed_formats_detect_corruption);
    RUN(concatenated_streams);
    RUN(bzip2_randomised_block_is_unsupported);
    RUN(xz_other_filters_are_unsupported);
    RUN(lzfse_block_kinds_are_covered);
    RUN(lzma_alone_size_field);
    RUN(encoders_round_trip);
    RUN(xz_encoder_chunk_limits);
    RUN(vectors_stream_at_every_buffer_size);
    RUN(deflate_reports_exact_consumption);
    RUN(pull_errors_are_reported);
    RUN(decoders_chain);
    RUN(stacked_decoder_owns_its_input);
    RUN(pull_close_owns_the_input);
    RUN(stated_checksums_are_verified);
    RUN(exact_size_overrides_the_stream);
    RUN(gzip_members);
    RUN(rle90_both_dialects);
    RUN(cpt_rle_escapes);
